class Solution { fun collectTheCoins(coins:IntArray,edges:Array<IntArray>):Int{val n=coins.size;val graph=Array(n){mutableListOf<Int>()};val degree=IntArray(n);for(edge in edges){graph[edge[0]].add(edge[1]);graph[edge[1]].add(edge[0]);degree[edge[0]]++;degree[edge[1]]++};val queue=java.util.ArrayDeque<Int>();for(node in 0 until n)if(degree[node]==1&&coins[node]==0)queue.add(node);while(queue.isNotEmpty()){val node=queue.removeFirst();if(degree[node]==0)continue;degree[node]=0;for(next in graph[node])if(degree[next]>0){degree[next]--;if(degree[next]==1&&coins[next]==0)queue.add(next)}};for(node in 0 until n)if(degree[node]==1)queue.add(node);repeat(2){repeat(queue.size){val node=queue.removeFirst();if(degree[node]>0){degree[node]=0;for(next in graph[node])if(degree[next]>0){degree[next]--;if(degree[next]==1)queue.add(next)}}}};return degree.sum()} }
